begin;
select plan(43);
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_user_meta_data) values
('40000000-0000-4000-8000-000000000001','authenticated','authenticated','flow-leader@test.invalid',now(),'{"nickname":"Leader"}'),
('40000000-0000-4000-8000-000000000002','authenticated','authenticated','flow-member@test.invalid',now(),'{"nickname":"Member"}'),
('40000000-0000-4000-8000-000000000003','authenticated','authenticated','flow-other@test.invalid',now(),'{"nickname":"Other"}');
insert into public.bands(id,name,leader_user_id) values
('40000000-0000-4000-8000-000000001001','Workflow band','40000000-0000-4000-8000-000000000001');
insert into public.band_members(id,band_id,user_id,part_key,part_label,role) values
('40000000-0000-4000-8000-000000002001','40000000-0000-4000-8000-000000001001','40000000-0000-4000-8000-000000000001','guitar','기타','leader'),
('40000000-0000-4000-8000-000000002002','40000000-0000-4000-8000-000000001001','40000000-0000-4000-8000-000000000002','guitar','기타','member');
set local role authenticated;
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","is_anonymous":false}',true);
select set_config('test.round',public.start_round('40000000-0000-4000-8000-000000001001')::text,true);
select set_config('test.today',(select start_date::text from public.planning_rounds where id=current_setting('test.round')::uuid),true);
select is((select end_date-start_date+1 from public.planning_rounds where id=current_setting('test.round')::uuid),60,'round spans exactly 60 days');
select is((select count(*)::integer from public.round_participants where round_id=current_setting('test.round')::uuid),2,'duplicate guitar parts are distinct round participants');
select set_config('test.song',public.add_song('40000000-0000-4000-8000-000000001001','Snapshot song','Artist')::text,true);
select public.update_song_difficulty(current_setting('test.song')::bigint,'guitar',2::smallint,0);
select public.cast_vote(current_setting('test.round')::uuid,current_setting('test.song')::bigint,'yes',null);
select lives_ok($$select public.save_unavailability(current_setting('test.round')::uuid,'[]',false)$$,'leader explicitly submits no unavailable days');
select is((select status from public.round_submissions where round_id=current_setting('test.round')::uuid and member_id='40000000-0000-4000-8000-000000002001'),'none','empty explicit submission is not pending');
select throws_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,current_setting('test.today')::date,array[current_setting('test.song')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),false)$$,'P0001','SUBMISSIONS_PENDING','finalization waits for every member submission');
select set_config('test.stale_version',(select version::text from public.planning_rounds where id=current_setting('test.round')::uuid),true);
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000002","is_anonymous":false}',true);
select lives_ok($$select public.save_unavailability(current_setting('test.round')::uuid,jsonb_build_array(jsonb_build_object('date',current_setting('test.today'),'reason','work'),jsonb_build_object('date',current_setting('test.today'),'reason','work')),false)$$,'identical duplicate unavailable dates save once');
select is((select count(*)::integer from public.unavailable_dates where member_id='40000000-0000-4000-8000-000000002002'),1,'duplicates produce one stored date');
select is((select status from public.round_submissions where round_id=current_setting('test.round')::uuid and member_id='40000000-0000-4000-8000-000000002001'),'none','member availability cannot overwrite leader submission');
select throws_ok($$select public.save_unavailability(current_setting('test.round')::uuid,jsonb_build_array(jsonb_build_object('date',current_setting('test.today'),'reason','changed'),jsonb_build_object('date','2026-02-30','reason','invalid')),true)$$,'P0001','INVALID_INPUT','mixed valid and invalid dates reject the entire save');
select is((select reason from public.unavailable_dates where member_id='40000000-0000-4000-8000-000000002002' and unavailable_date=current_setting('test.today')::date),'work','failed batch preserves previous reason');
select throws_ok($$select public.save_unavailability(current_setting('test.round')::uuid,'{}',false)$$,'P0001','INVALID_INPUT','non-array batch rejected');
select throws_ok($$select public.save_unavailability(current_setting('test.round')::uuid,jsonb_build_array(jsonb_build_object('date',current_setting('test.today'),'reason',' ')),false)$$,'P0001','INVALID_INPUT','blank unavailable reason rejected');
select throws_ok($$select public.save_unavailability(current_setting('test.round')::uuid,jsonb_build_array(jsonb_build_object('date',(current_setting('test.today')::date-1)::text,'reason','past')),true)$$,'P0001','INVALID_INPUT','past dates rejected');
select throws_ok($$select public.save_unavailability(current_setting('test.round')::uuid,jsonb_build_array(jsonb_build_object('date',current_setting('test.today'),'reason','a'),jsonb_build_object('date',current_setting('test.today'),'reason','b')),false)$$,'P0001','DUPLICATE_CONFLICT','conflicting duplicate reasons rejected');
select is((select count(*)::integer from public.unavailable_dates where member_id='40000000-0000-4000-8000-000000002002'),1,'invalid saves do not partially replace existing dates');
select throws_ok($$select public.save_unavailability(current_setting('test.round')::uuid,jsonb_build_array(jsonb_build_object('date',(current_setting('test.today')::date+60)::text,'reason','outside')),false)$$,'P0001','OUTSIDE_ACK_REQUIRED','outside-round date requires acknowledgement');
select lives_ok($$select public.save_unavailability(current_setting('test.round')::uuid,jsonb_build_array(jsonb_build_object('date',(current_setting('test.today')::date+60)::text,'reason','outside')),true)$$,'outside-round dates save with explicit acknowledgement');
select is((select status from public.round_submissions where round_id=current_setting('test.round')::uuid and member_id='40000000-0000-4000-8000-000000002002'),'none','outside-only save counts as no unavailability inside this round');
select lives_ok($$select public.save_unavailability(current_setting('test.round')::uuid,jsonb_build_array(jsonb_build_object('date',current_setting('test.today'),'reason','work')),false)$$,'current-round dates save while previously stored future dates are retained');
select is((select count(*)::integer from public.unavailable_dates where member_id='40000000-0000-4000-8000-000000002002'),2,'saving the round preserves future outside-round dates');
select throws_ok($$select public.cast_vote(current_setting('test.round')::uuid,current_setting('test.song')::bigint,'no',' ')$$,'P0001','INVALID_INPUT','negative vote requires a reason');
select public.cast_vote(current_setting('test.round')::uuid,current_setting('test.song')::bigint,'no','need practice');
select public.cast_vote(current_setting('test.round')::uuid,current_setting('test.song')::bigint,'yes','obsolete reason');
select is((select reason from public.song_votes where round_id=current_setting('test.round')::uuid and member_id='40000000-0000-4000-8000-000000002002'),null::text,'changing no to yes removes the old reason');
select throws_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,current_setting('test.today')::date,array[current_setting('test.song')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),true)$$,'P0001','FORBIDDEN','ordinary member cannot finalize');
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000003',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000003","is_anonymous":false}',true);
select throws_ok($$select public.save_unavailability(current_setting('test.round')::uuid,'[]',false)$$,'P0001','FORBIDDEN','outsider cannot submit another band availability');
select throws_ok($$select public.cast_vote(current_setting('test.round')::uuid,current_setting('test.song')::bigint,'yes',null)$$,'P0001','FORBIDDEN','outsider cannot vote in another band');
select is((select count(*)::integer from public.planning_rounds),0,'outsider cannot read this band rounds');
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","is_anonymous":false}',true);
select throws_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,current_setting('test.today')::date,array[current_setting('test.song')::bigint],current_setting('test.stale_version')::bigint,true)$$,'P0001','ROUND_STALE','stale finalization version rejected');
select throws_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,current_setting('test.today')::date,array[current_setting('test.song')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),false)$$,'P0001','PARTIAL_ACK_REQUIRED','partial attendance requires a fresh acknowledgement');
select lives_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,current_setting('test.today')::date,array[current_setting('test.song')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),true)$$,'eligible partial rehearsal finalizes');
select set_config('test.plan',(select id::text from public.confirmed_plans where band_id='40000000-0000-4000-8000-000000001001'),true);
select is((select attendee_count from public.confirmed_plans where id=current_setting('test.plan')::uuid),1,'confirmed attendance reflects current unavailability');
select is((select count(*)::integer from public.confirmed_plan_members where plan_id=current_setting('test.plan')::uuid),2,'snapshot includes every round member');
select public.update_song_difficulty(current_setting('test.song')::bigint,'guitar',5::smallint,1);
select is((select title_snapshot from public.confirmed_plan_songs where plan_id=current_setting('test.plan')::uuid),'Snapshot song','later difficulty changes preserve confirmed song snapshot');
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000002","is_anonymous":false}',true);
select public.save_unavailability(current_setting('test.round')::uuid,'[]',false);
select is((select reason_snapshot from public.confirmed_plan_members where plan_id=current_setting('test.plan')::uuid and source_member_id='40000000-0000-4000-8000-000000002002'),'work','later availability edits preserve confirmed absence reason');
select public.cast_vote(current_setting('test.round')::uuid,current_setting('test.song')::bigint,'no','practice first');
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","is_anonymous":false}',true);
select throws_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,(current_setting('test.today')::date+1),array[current_setting('test.song')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),false)$$,'P0001','SONG_NOT_ELIGIBLE','failed re-finalization rechecks latest votes');
select is((select id::text from public.confirmed_plans where band_id='40000000-0000-4000-8000-000000001001'),current_setting('test.plan'),'failed replacement preserves previous plan');
select throws_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,current_setting('test.today')::date,array[current_setting('test.song')::bigint,current_setting('test.song')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),false)$$,'P0001','INVALID_INPUT','duplicate selected songs rejected atomically');
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000002","is_anonymous":false}',true);
select public.cast_vote(current_setting('test.round')::uuid,current_setting('test.song')::bigint,'yes',null);
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","is_anonymous":false}',true);
select lives_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,(current_setting('test.today')::date+1),array[current_setting('test.song')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),false)$$,'eligible re-finalization succeeds');
select is((select count(*)::integer from public.confirmed_plans where band_id='40000000-0000-4000-8000-000000001001'),2,'both confirmed plans remain');
select is((select attendee_count from public.confirmed_plans where band_id='40000000-0000-4000-8000-000000001001' and rehearsal_date=current_setting('test.today')::date+1),2,'new snapshot reflects updated attendance');
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000002","is_anonymous":false}',true);
select lives_ok($$select public.leave_band()$$,'ordinary member can leave');
select set_config('request.jwt.claim.sub','40000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","is_anonymous":false}',true);
select is((select status from public.planning_rounds where id=current_setting('test.round')::uuid),'invalidated','participant leaving invalidates active round');
select is((select count(*)::integer from public.confirmed_plans where band_id='40000000-0000-4000-8000-000000001001'),2,'leaving preserves both confirmed snapshots');
select throws_ok($$select public.confirm_rehearsal_plan(current_setting('test.round')::uuid,current_setting('test.today')::date,array[current_setting('test.song')::bigint],(select version from public.planning_rounds where id=current_setting('test.round')::uuid),true)$$,'P0001','ROUND_INVALID','invalidated round cannot be finalized');
select * from finish();
rollback;
